<?php
/** File 06 Future Knowledge Intelligence: F06-FUT-001..018. */
defined( 'ABSPATH' ) || exit;

final class HE_V23_Future_Intelligence {
    const DB_VERSION = 1;
    const OPTION_DB_VERSION = 'he_v23_future_db_version';
    const CRON_HOOK = 'he_v23_evidence_watch';
    const NS = 'sabri/v2/file-06/future';

    public static function hooks() {
        add_action( 'rest_api_init', array( __CLASS__, 'routes' ) );
        add_action( self::CRON_HOOK, array( __CLASS__, 'scheduled_evidence_watch' ) );
        add_filter( 'sabri_notification_event_catalog', array( __CLASS__, 'notification_events' ) );
        add_filter( 'sabri_platform_contracts', array( __CLASS__, 'extend_contract' ), 120 );
        add_filter( 'sabri_publishing_dashboard_providers', array( __CLASS__, 'dashboard_projection' ), 120 );
        add_action( 'EncyclopediaEntryPublished.v1', array( __CLASS__, 'on_native_change' ), 10, 2 );
        add_action( 'EncyclopediaEntryCorrected.v1', array( __CLASS__, 'on_native_change' ), 10, 2 );
        add_action( 'EncyclopediaEntryRetracted.v1', array( __CLASS__, 'on_native_change' ), 10, 2 );
        add_action( 'KnowledgeConceptMerged.v1', array( __CLASS__, 'on_native_change' ), 10, 2 );
        if ( ! wp_next_scheduled( self::CRON_HOOK ) ) {
            wp_schedule_event( time() + HOUR_IN_SECONDS, 'daily', self::CRON_HOOK );
        }
    }

    public static function activate() {
        self::install_schema();
        if ( ! wp_next_scheduled( self::CRON_HOOK ) ) {
            wp_schedule_event( time() + HOUR_IN_SECONDS, 'daily', self::CRON_HOOK );
        }
    }

    public static function deactivate() {
        $timestamp = wp_next_scheduled( self::CRON_HOOK );
        if ( $timestamp ) { wp_unschedule_event( $timestamp, self::CRON_HOOK ); }
    }

    private static function table( $suffix ) { global $wpdb; return $wpdb->prefix . 'he_' . $suffix; }

    public static function install_schema() {
        global $wpdb;
        require_once ABSPATH . 'wp-admin/includes/upgrade.php';
        $charset = $wpdb->get_charset_collate();
        $claims = self::table( 'claims' );
        $prov = self::table( 'provenance' );
        $external = self::table( 'external_links' );
        $translations = self::table( 'translations' );
        $watches = self::table( 'watches' );
        $impact = self::table( 'impact_queue' );
        $gaps = self::table( 'evidence_gaps' );
        dbDelta( "CREATE TABLE {$claims} ( id bigint unsigned NOT NULL AUTO_INCREMENT, public_id char(36) NOT NULL, concept_id bigint unsigned NOT NULL, version_no int unsigned NOT NULL DEFAULT 0, claim_text longtext NOT NULL, claim_type varchar(40) NOT NULL DEFAULT 'factual', evidence_state varchar(24) NOT NULL DEFAULT 'uncertain', confidence decimal(5,4) NOT NULL DEFAULT 0, content_hash char(64) NOT NULL, status varchar(24) NOT NULL DEFAULT 'draft', created_by bigint unsigned NOT NULL DEFAULT 0, reviewed_by bigint unsigned NOT NULL DEFAULT 0, created_at datetime NOT NULL, updated_at datetime NOT NULL, PRIMARY KEY (id), UNIQUE KEY public_id (public_id), KEY concept_version (concept_id,version_no), KEY state_status (evidence_state,status), KEY content_hash (content_hash) ) {$charset};" );
        dbDelta( "CREATE TABLE {$prov} ( id bigint unsigned NOT NULL AUTO_INCREMENT, object_type varchar(32) NOT NULL, object_id varchar(80) NOT NULL, action varchar(48) NOT NULL, actor_id bigint unsigned NOT NULL DEFAULT 0, source_uri text NULL, source_identifier varchar(190) NULL, source_type varchar(48) NULL, transform varchar(80) NULL, parent_hash char(64) NULL, record_hash char(64) NOT NULL, payload_json longtext NULL, created_at datetime NOT NULL, PRIMARY KEY (id), KEY object_lookup (object_type,object_id), KEY source_identifier (source_identifier), KEY record_hash (record_hash) ) {$charset};" );
        dbDelta( "CREATE TABLE {$external} ( id bigint unsigned NOT NULL AUTO_INCREMENT, object_type varchar(32) NOT NULL, object_id varchar(80) NOT NULL, provider varchar(32) NOT NULL, external_id varchar(190) NOT NULL, relation varchar(40) NOT NULL DEFAULT 'related', metadata_json longtext NULL, status varchar(32) NOT NULL DEFAULT 'active', last_checked_at datetime NULL, next_check_at datetime NULL, created_at datetime NOT NULL, updated_at datetime NOT NULL, PRIMARY KEY (id), UNIQUE KEY provider_external_object (provider,external_id,object_type,object_id), KEY watch_due (status,next_check_at), KEY object_lookup (object_type,object_id) ) {$charset};" );
        dbDelta( "CREATE TABLE {$translations} ( id bigint unsigned NOT NULL AUTO_INCREMENT, concept_id bigint unsigned NOT NULL, source_language varchar(16) NOT NULL, target_language varchar(16) NOT NULL, source_version int unsigned NOT NULL DEFAULT 0, translation_version int unsigned NOT NULL DEFAULT 1, content_json longtext NOT NULL, status varchar(28) NOT NULL DEFAULT 'draft', machine_assisted tinyint(1) NOT NULL DEFAULT 0, translator_id bigint unsigned NOT NULL DEFAULT 0, reviewer_id bigint unsigned NOT NULL DEFAULT 0, content_hash char(64) NOT NULL, created_at datetime NOT NULL, updated_at datetime NOT NULL, PRIMARY KEY (id), UNIQUE KEY concept_language_version (concept_id,target_language,translation_version), KEY outdated (concept_id,source_version,status), KEY content_hash (content_hash) ) {$charset};" );
        dbDelta( "CREATE TABLE {$watches} ( id bigint unsigned NOT NULL AUTO_INCREMENT, user_id bigint unsigned NOT NULL, object_type varchar(32) NOT NULL, object_id varchar(80) NOT NULL, event_mask varchar(190) NOT NULL DEFAULT 'updated,corrected,retracted', created_at datetime NOT NULL, PRIMARY KEY (id), UNIQUE KEY user_object (user_id,object_type,object_id), KEY object_lookup (object_type,object_id) ) {$charset};" );
        dbDelta( "CREATE TABLE {$impact} ( id bigint unsigned NOT NULL AUTO_INCREMENT, source_type varchar(32) NOT NULL, source_id varchar(80) NOT NULL, source_event varchar(64) NOT NULL, consumer_file varchar(24) NOT NULL, consumer_ref varchar(190) NULL, state varchar(24) NOT NULL DEFAULT 'pending', reason varchar(190) NULL, attempts smallint unsigned NOT NULL DEFAULT 0, created_at datetime NOT NULL, updated_at datetime NOT NULL, PRIMARY KEY (id), KEY pending_consumer (state,consumer_file), KEY source_lookup (source_type,source_id) ) {$charset};" );
        dbDelta( "CREATE TABLE {$gaps} ( id bigint unsigned NOT NULL AUTO_INCREMENT, concept_id bigint unsigned NOT NULL, gap_type varchar(40) NOT NULL, severity varchar(16) NOT NULL DEFAULT 'medium', state varchar(24) NOT NULL DEFAULT 'open', detail_json longtext NULL, detected_at datetime NOT NULL, resolved_at datetime NULL, PRIMARY KEY (id), UNIQUE KEY concept_gap (concept_id,gap_type), KEY state_severity (state,severity) ) {$charset};" );
        update_option( self::OPTION_DB_VERSION, self::DB_VERSION, false );
    }

    private static function now() { return current_time( 'mysql', true ); }
    private static function json( $value ) { return wp_json_encode( $value, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES ); }
    private static function decode( $json ) { $v = json_decode( (string) $json, true ); return is_array( $v ) ? $v : array(); }
    private static function clean_id( $value ) { return substr( sanitize_text_field( (string) $value ), 0, 190 ); }
    private static function uuid() { return function_exists( 'wp_generate_uuid4' ) ? wp_generate_uuid4() : uniqid( 'he-', true ); }
    private static function hash( $value ) { return hash( 'sha256', is_string( $value ) ? $value : self::json( $value ) ); }
    private static function concept( $id ) { $row = HE_V2_Domain::concept_by_id( $id, true ); if ( ! $row && ctype_digit( (string) $id ) ) { $row = HE_V2_Domain::concept_by_id( absint( $id ), true ); } return $row; }
    private static function editorial_permission( $cap = null ) { return HE_V2_Auth::rest_permission( $cap ?: HE_V2_Auth::CAP_EDIT ); }

    public static function routes() {
        $read = '__return_true';
        register_rest_route( self::NS, '/claims', array( array( 'methods'=>WP_REST_Server::READABLE,'callback'=>array(__CLASS__,'claims_list'),'permission_callback'=>$read ), array( 'methods'=>WP_REST_Server::CREATABLE,'callback'=>array(__CLASS__,'claims_create'),'permission_callback'=>array(__CLASS__,'can_edit') ) ) );
